from pathlib import Path

test_path = Path('project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py')
text = test_path.read_text(encoding='utf-8')
marker = '''    def test_corrupt_candidate_recovery_is_rejected(self) -> None:
        with mock.patch.object(
            evaluator.knowledge_projection,
            'recover_projection',
            return_value=[],
        ):
            errors, report = self._evaluate()
        self.assertTrue(errors)
        self.assertFalse(report['candidate']['exact_source_coverage'])
        self.assertFalse(report['candidate']['lossless_reconstruction'])

'''
addition = marker + '''    def test_extra_recovered_candidate_source_is_rejected(self) -> None:
        original_recover = evaluator.knowledge_projection.recover_projection
        injected = False

        def recover_with_extra(data: bytes) -> list[dict[str, object]]:
            nonlocal injected
            recovered = original_recover(data)
            if recovered and not injected:
                injected = True
                recovered.append(
                    {
                        'metadata': {'id': 'knowledge.unexpected.extra'},
                        'content': b'unexpected extra source',
                    }
                )
            return recovered

        with mock.patch.object(
            evaluator.knowledge_projection,
            'recover_projection',
            side_effect=recover_with_extra,
        ):
            errors, report = self._evaluate()
        self.assertTrue(errors)
        self.assertTrue(
            any(
                'not losslessly recoverable' in error
                or 'source coverage' in error
                for error in errors
            ),
            errors,
        )
        self.assertFalse(report['candidate']['exact_source_coverage'])
        self.assertFalse(report['candidate']['lossless_reconstruction'])
        self.assertEqual(report['decision']['recommended'], 'REVISE')

'''
if text.count(marker) != 1:
    raise SystemExit(f'expected one corrupt-recovery test marker, found {text.count(marker)}')
test_path.write_text(text.replace(marker, addition, 1), encoding='utf-8')

